import sys

def main():
    lines = []
    try:
        for _ in range(5):
            line = sys.stdin.readline()
            if not line:
                break
            lines.append(line.strip())
    except EOFError:
        pass

    cia_indices = []
    for i, code in enumerate(lines):
        if "FBI" in code:
            cia_indices.append(i + 1)

    if not cia_indices:
        print("HE GOT AWAY!")
    else:
        print(" ".join(map(str, sorted(cia_indices))))

if __name__ == "__main__":
    main()
